/* A host stand-in for the parts of Felucca's lcd.c / gfx.c that src/ui_seq_draw.c calls (the canvas, RGB, the faces;
 * the page brings its own colours), with the same names and signatures, drawing into a 240 x 240 RGB565 framebuffer
 * (shim_fb). Test and emulator scaffolding only: the FM1 build uses Felucca's own canvas.
 *
 * Shapes are rasterised here. Text cannot be (Felucca's faces are generated by its build and are not in this repo), so
 * each text call is kept with its canvas position and colour, and handed with its region to shim_on_blit(), which the
 * includer defines: render_seq_screen.c logs it for seq_screen_png.py, web_seq_screen.c passes it to the browser.
 * Text is measured with seq_shim_metrics.h (Segoe UI advances from seq_screen_png.py metrics), so centring, right
 * alignment and the fit checks run on real widths.
 *
 * Include once, before ui_seq_draw.c. */
#pragma once
#include <stdint.h>
#include <string.h>
#include "seq_shim_metrics.h"

#define RGB(r, g, b) ((uint16_t)((((r) >> 3) << 11) | (((g) >> 2) << 5) | ((b) >> 3)))
typedef struct { uint8_t h, asc; char id; const uint8_t *adv; } aafont_t;
static const aafont_t AF_S = {SHIM_S_H, SHIM_S_ASC, 'S', SHIM_ADV_S};
static const aafont_t AF_M = {SHIM_M_H, SHIM_M_ASC, 'M', SHIM_ADV_M};
#define HALF_UP(v) ((v) >> 1)
#define CAP_IN(F, h) (HALF_UP((h) - AF_##F##_CAP_H) - AF_##F##_CAP_Y)

typedef struct { int16_t x, y; char face; uint16_t col; char s[40]; } ShimText;   /* canvas coordinates */
#define SHIM_TEXT_MAX 64

static uint16_t shim_fb[240 * 240];
static uint16_t shim_cv[240 * 124];
static int32_t cv_w, cv_h;
static uint16_t cv_bg;
static ShimText shim_text[SHIM_TEXT_MAX];
static int shim_ntext;
static int shim_cuts, shim_overflows;       /* text that did not fit its slot / its canvas */

/* defined by the includer: a region was blitted to (x, y, w, h) on the framebuffer, carrying these texts */
static void shim_on_blit(uint32_t x, uint32_t y, uint32_t w, uint32_t h, const ShimText *t, int n);

static void lcd_fill(uint32_t x, uint32_t y, uint32_t w, uint32_t h, uint16_t c)
{
    uint32_t i, j;
    for (j = y; j < y + h && j < 240u; j++)
        for (i = x; i < x + w && i < 240u; i++)
            shim_fb[j * 240u + i] = c;
    shim_on_blit(x, y, w, h, 0, 0);
}

static void cv_begin(uint32_t w, uint32_t h, uint16_t bg)
{
    int32_t i;
    cv_w = (int32_t)w; cv_h = (int32_t)h; cv_bg = bg; shim_ntext = 0;
    for (i = 0; i < cv_w * cv_h; i++) shim_cv[i] = bg;
}

static void cv_blit(uint32_t x, uint32_t y)
{
    int32_t i, j;
    for (j = 0; j < cv_h; j++)
        for (i = 0; i < cv_w; i++)
            shim_fb[(y + (uint32_t)j) * 240u + x + (uint32_t)i] = shim_cv[j * cv_w + i];
    shim_on_blit(x, y, (uint32_t)cv_w, (uint32_t)cv_h, shim_text, shim_ntext);
}

static inline void cv_pset(int32_t x, int32_t y, uint16_t c)
{
    if (x >= 0 && x < cv_w && y >= 0 && y < cv_h) shim_cv[y * cv_w + x] = c;
}

static void cv_rect(int32_t x, int32_t y, int32_t w, int32_t h, uint16_t c)
{
    int32_t i, j;
    for (j = y; j < y + h; j++)
        for (i = x; i < x + w; i++)
            cv_pset(i, j, c);
}

static void cv_frame(int32_t x, int32_t y, int32_t w, int32_t h, uint16_t c)
{
    cv_rect(x, y, w, 1, c); cv_rect(x, y + h - 1, w, 1, c); cv_rect(x, y, 1, h, c); cv_rect(x + w - 1, y, 1, h, c);
}

static void cv_line(int32_t x0, int32_t y0, int32_t x1, int32_t y1, uint16_t c)
{
    int32_t dx = x1 > x0 ? x1 - x0 : x0 - x1, sx = x0 < x1 ? 1 : -1, dy = y1 > y0 ? y0 - y1 : y1 - y0, sy = y0 < y1 ? 1 : -1;
    int32_t err = dx + dy, e2;
    for (;;) {
        cv_pset(x0, y0, c);
        if (x0 == x1 && y0 == y1) break;
        e2 = 2 * err;
        if (e2 >= dy) { err += dy; x0 += sx; }
        if (e2 <= dx) { err += dx; y0 += sy; }
    }
}

/* FLAT style: rounded corners (un-antialiased here) */
static void cv_rrect(int32_t x, int32_t y, int32_t w, int32_t h, int32_t r, uint16_t c, uint16_t under)
{
    int32_t i, j;
    (void)under;
    if (r < 0) r = -r;
    if (r > w / 2) r = w / 2;
    if (r > h / 2) r = h / 2;
    for (j = 0; j < h; j++)
        for (i = 0; i < w; i++) {
            int32_t cx = i < r ? r - i : i >= w - r ? i - (w - r - 1) : 0, cy = j < r ? r - j : j >= h - r ? j - (h - r - 1) : 0;
            if (cx * cx + cy * cy <= r * r + r / 2 || cx == 0 || cy == 0)
                cv_pset(x + i, y + j, c);
        }
}

static inline int32_t text_w(const aafont_t *f, const char *s)
{
    int32_t w = 0;
    for (; *s; s++)
        w += (*s >= 32 && *s < 127) ? f->adv[*s - 32] : f->adv['?' - 32];
    return w;
}

static inline int32_t cv_text_on(int32_t x, int32_t y, const aafont_t *f, const char *s, uint16_t fg, uint16_t bg)
{
    int32_t w = text_w(f, s);
    (void)bg;
    if (x < 0 || x + w > cv_w || y + AF_S_CAP_Y < 0 || y + f->h > cv_h + 3)
        shim_overflows++;
    if (shim_ntext < SHIM_TEXT_MAX) {
        ShimText *p = &shim_text[shim_ntext++];
        p->x = (int16_t)x; p->y = (int16_t)y; p->face = f->id; p->col = fg;
        strncpy(p->s, s, sizeof p->s - 1); p->s[sizeof p->s - 1] = '\0';
    }
    return x + w;
}
static inline int32_t cv_text(int32_t x, int32_t y, const aafont_t *f, const char *s, uint16_t fg)
{
    return cv_text_on(x, y, f, s, fg, cv_bg);
}
static inline int32_t cv_text_r(int32_t xr, int32_t y, const aafont_t *f, const char *s, uint16_t fg, uint16_t bg)
{
    int32_t w = text_w(f, s);
    cv_text_on(xr - w, y, f, s, fg, bg);
    return xr - w;
}
static inline int32_t cv_text_in(int32_t x0, int32_t y, int32_t w, const aafont_t *f, const char *s, uint16_t fg, uint16_t bg)
{
    return cv_text_on(x0 + HALF_UP(w - text_w(f, s)), y, f, s, fg, bg);
}
static inline int32_t cv_text_fit(int32_t x, int32_t y, const aafont_t *f, const char *s, uint16_t fg, uint16_t bg, int32_t maxw)
{
    if (text_w(f, s) > maxw)
        shim_cuts++;
    return cv_text_on(x, y, f, s, fg, bg);
}
